/**
 * Register every skill as an MCP prompt.
 *
 * Prefers the Firebase-backed cache. Falls back to the compiled snapshot only
 * when the cache is empty, which means the startup Firebase read failed.
 */
export function registerSkillPrompts(server: McpServer): void {
  const cached = getAllCachedSkills();
  const entries: { name: string; description: string; content: string }[] =
    cached.length > 0 ? cached : SKILL_REGISTRY;

  if (cached.length === 0) {
    console.warn(
      `[skills] Cache empty — registering ${SKILL_REGISTRY.length} prompts from the compiled snapshot`,
    );
  }

  for (const skill of entries) {
    server.prompt(
      skill.name,
      skill.description,
      {},
      async () => ({
        messages: [{
          role: "user" as const,
          content: { type: "text" as const, text: skill.content },
        }],
      }),
    );
  }
}

/** Compiled snapshot, used by skill-cache.ts when Firebase is unreachable. */
export function getCompiledSkillRegistry(): SkillEntry[] {
  return SKILL_REGISTRY;
}
